--
-- Name: GroupedAsinView; Type: VIEW; Schema: public; Owner: viasuser
--

CREATE VIEW public."GroupedAsinView" AS
 SELECT (EXISTS ( SELECT 1
           FROM public."PrivateLabel" pl
          WHERE ((pl."brandId" = b.id) AND (pl."manufacturerId" = m.id)))) AS "isPrivate",
    m.name AS "Manufacturer",
    b.name AS "Brand",
    count(a.id) AS "AsinCount",
    string_agg(a.code, ', '::text) AS "AsinsList"
   FROM ((public."ASIN" a
     JOIN public."Brand" b ON ((b.id = a."brandId")))
     JOIN public."Manufacturer" m ON ((m.id = a."manufacturerId")))
  GROUP BY m.id, m.name, b.id, b.name
  ORDER BY (count(a.id)) DESC;


ALTER VIEW public."GroupedAsinView" OWNER TO viasuser;

--
-- Name: FiltredGroupedAsinView; Type: VIEW; Schema: public; Owner: viasuser
--

CREATE VIEW public."FiltredGroupedAsinView" AS
 SELECT "GroupedAsinView"."Manufacturer",
    "GroupedAsinView"."Brand",
    "GroupedAsinView"."AsinCount",
    "GroupedAsinView"."AsinsList"
   FROM public."GroupedAsinView"
  WHERE ("GroupedAsinView"."isPrivate" = false);


